<template>
  <AppLayout>
    <div class="mx-auto max-w-6xl space-y-5">
      <AdminPageHeader :title="text('分层安全限制', 'Layered API restrictions')" :description="text('复用现有内容审核和提示词审计，不增加扫描器或收费；只限制 API，不关闭用户的网站登录。', 'Reuses existing moderation and prompt audits. Adds no scanner or charge. Only API access is restricted; website sign-in remains available.')" />
      <p v-if="error" role="alert" class="rounded-lg bg-red-50 p-3 text-red-700 dark:bg-red-950">{{ error }}</p>
      <p v-if="success" role="status" class="text-sm text-green-700">{{ success }}</p>
      <form v-if="config" class="card space-y-5 p-5" @submit.prevent="save">
        <div class="flex flex-wrap gap-6"><label class="flex gap-2"><input v-model="config.enabled" type="checkbox" />{{ text('启用分层限制', 'Enable layered restrictions') }}</label><label class="flex gap-2"><input v-model="config.observe_only" type="checkbox" />{{ text('只观察，不执行限制', 'Observe without enforcement') }}</label></div>
        <p v-if="!config.risk_control_enabled" class="text-sm text-amber-700">{{ text('风控总开关未开启，本规则不会执行。', 'The main risk-control switch is off; this policy is inactive.') }}</p>
        <div class="grid gap-4 md:grid-cols-2"><label class="block text-sm">{{ text('处罚方式', 'Policy') }}<select v-model="config.policy" class="input mt-2 w-full"><option value="session_block">{{ text('达到阈值后禁止该会话', 'Block conversation at threshold') }}</option><option value="user_block">{{ text('全部 Key 累计，达到阈值后禁止用户 API', 'Count across all keys and block user API') }}</option><option value="session_route_then_block">{{ text('先限制分组，再禁止该会话', 'Restrict group, then block conversation') }}</option></select></label><label class="block text-sm">{{ text('违规次数阈值', 'Strike threshold') }}<input v-model.number="config.threshold" type="number" min="1" max="1000" class="input mt-2 w-full" required /></label><label class="block text-sm">{{ text('累计窗口（小时）', 'Counting window (hours)') }}<input v-model.number="config.window_hours" type="number" min="1" max="87600" class="input mt-2 w-full" required /></label><label class="block text-sm">{{ text('限制有效期（小时）', 'Restriction duration (hours)') }}<input v-model.number="config.duration_hours" type="number" min="1" max="87600" class="input mt-2 w-full" required /></label><label v-if="config.policy === 'session_route_then_block'" class="block text-sm">{{ text('受限分组', 'Restricted group') }}<select v-model="config.target_group_id" class="input mt-2 w-full" required><option :value="null" disabled>{{ text('请选择分组', 'Select a group') }}</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }} · {{ group.platform }}</option></select></label></div>
        <p v-if="config.policy === 'session_route_then_block'" class="text-sm text-gray-500">{{ text('首次命中后只接受用户原本有权使用的受限分组，不自动授予分组、改倍率或迁移订阅；达到阈值后封禁该会话。', 'After the first strike, only the configured group is admitted, subject to existing permissions. No group access, rate or subscription is granted or changed. The conversation is blocked at the threshold.') }}</p>
        <label class="flex gap-2 text-sm"><input v-model="config.all_groups" type="checkbox" />{{ text('统计全部分组的违规', 'Count findings from all groups') }}</label><div v-if="!config.all_groups" class="space-y-2 text-sm"><p>{{ text('统计以下分组的违规', 'Count findings from selected groups') }}</p><GroupSelector v-model="config.group_ids" :groups="groups" :searchable="true" /></div><label class="block text-sm">{{ text('豁免用户 ID（逗号分隔）', 'Exempt user IDs (comma separated)') }}<input v-model="exemptIDs" class="input mt-2 w-full" /></label><p class="text-xs text-gray-500">{{ text('会话级策略按用户身份跨 Key 累计；没有明确会话标识时仅记录，不扩大封禁范围。用户级策略始终按用户全部 Key 累计，不依赖会话标识。观察模式切换到执行后，现有累计仍可能生效。', 'Session policies count across keys for the same user; missing conversation identity records only without widening scope. User policies count all keys even without a conversation identity. Existing strikes may become active when leaving observe mode.') }}</p><button class="btn btn-primary" :disabled="busy">{{ text('保存', 'Save') }}</button>
      </form>
      <section class="card space-y-4 p-5"><h2 class="font-semibold">{{ text('安全记录与人工解除', 'Security records and manual release') }}</h2><form class="flex flex-wrap gap-3" @submit.prevent="page = 1; loadEvents()"><input v-model.number="userID" type="number" min="1" class="input" :placeholder="text('用户 ID，可留空', 'User ID, optional')" /><button class="btn btn-secondary" :disabled="busy">{{ text('查询', 'Search') }}</button></form><form class="flex flex-wrap gap-3" @submit.prevent="release"><input v-model.trim="releaseReason" class="input min-w-0 flex-1" :placeholder="text('解除原因（必填）', 'Release reason (required)')" required maxlength="1000" /><button class="btn btn-secondary" :disabled="busy || !userID || !releaseReason">{{ text('解除此用户的 API 限制', 'Release this user’s API restrictions') }}</button></form><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-gray-500"><tr><th class="p-3">{{ text('时间', 'Time') }}</th><th class="p-3">{{ text('用户', 'User') }}</th><th class="p-3">{{ text('原因', 'Reason') }}</th><th class="p-3">{{ text('累计', 'Strikes') }}</th><th class="p-3">Request ID</th></tr></thead><tbody><tr v-for="event in events" :key="event.id" class="border-t border-gray-100 dark:border-dark-700"><td class="p-3 whitespace-nowrap">{{ new Date(event.created_at).toLocaleString() }}</td><td class="p-3">#{{ event.user_id }}</td><td class="p-3">{{ event.reason }}</td><td class="p-3">{{ event.count }}</td><td class="p-3"><code class="break-all text-xs">{{ event.request_id }}</code></td></tr><tr v-if="!events.length"><td colspan="5" class="p-6 text-center text-gray-500">{{ text('暂无记录', 'No records') }}</td></tr></tbody></table></div><div class="flex justify-end gap-3"><button class="btn btn-secondary" :disabled="busy || page <= 1" @click="page--; loadEvents()">{{ text('上一页', 'Previous') }}</button><span class="self-center">{{ page }}</span><button class="btn btn-secondary" :disabled="busy || page * 20 >= total" @click="page++; loadEvents()">{{ text('下一页', 'Next') }}</button></div></section>
    </div>
  </AppLayout>
</template>
<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import AdminPageHeader from '@/components/admin/page/AdminPageHeader.vue'
import GroupSelector from '@/components/common/GroupSelector.vue'
import { getAll as getGroups } from '@/api/admin/groups'
import type { AdminGroup } from '@/types'
import { getPenaltyConfig, savePenaltyConfig, adminPenaltyEvents, releasePenalty, type PenaltyConfig, type PenaltyEvent } from '@/api/securityPenalties'
const { locale } = useI18n()
const text = (zh: string, en: string) => locale.value.startsWith('zh') ? zh : en
const groups = ref<AdminGroup[]>([])
const config = ref<PenaltyConfig>(), exemptIDs = ref(''), userID = ref<number>(), releaseReason = ref(''), events = ref<PenaltyEvent[]>([]), page = ref(1), total = ref(0), busy = ref(false), error = ref(''), success = ref('')
let disposed = false
function parseIDs(value: string) { const ids = value.trim() ? value.split(/[\s,，]+/).map(Number) : []; if (ids.some(id => !Number.isSafeInteger(id) || id <= 0)) throw new Error(text('ID 必须是正整数', 'IDs must be positive integers')); return [...new Set(ids)] }
async function loadEvents() { try { const data = await adminPenaltyEvents(page.value, userID.value || undefined); if (!disposed) { events.value = data.items; total.value = data.total } } catch (cause) { if (!disposed) error.value = (cause as Error).message } }
async function save() { if (!config.value || busy.value) return; busy.value = true; error.value = ''; success.value = ''; try { const input = { ...config.value, group_ids: [...config.value.group_ids], exempt_user_ids: parseIDs(exemptIDs.value) }; config.value = await savePenaltyConfig(input); success.value = text('已保存，新请求按新规则检查。', 'Saved. New requests use the updated policy.') } catch (cause) { error.value = (cause as Error).message } finally { busy.value = false } }
async function release() { if (!userID.value || !releaseReason.value || busy.value || !window.confirm(text('确认解除该用户的全部 API 限制？历史记录仍会保留。', 'Release all API restrictions for this user? Historical events are retained.'))) return; busy.value = true; error.value = ''; try { await releasePenalty(userID.value, releaseReason.value); releaseReason.value = ''; success.value = text('已解除，后续违规重新累计。', 'Released. Future findings start a new count.'); await loadEvents() } catch (cause) { error.value = (cause as Error).message } finally { busy.value = false } }
onMounted(async () => { try { const [data, options] = await Promise.all([getPenaltyConfig(), getGroups()]); if (!disposed) { config.value = data; groups.value = options; exemptIDs.value = data.exempt_user_ids.join(', ') } } catch (cause) { if (!disposed) error.value = (cause as Error).message } await loadEvents() })
onUnmounted(() => { disposed = true })
</script>
